/* Cifra una propuesta HTML con contraseña (AES-GCM + PBKDF2) y la envuelve en
   una pantalla de desbloqueo con aviso de confidencialidad.
   - Cifrado con WebCrypto (portable: Node crypto.webcrypto y navegador crypto.subtle usan los MISMOS parámetros).
   - El navegario descifra solo con la contraseña correcta Y tras aceptar la confidencialidad.
   Uso CLI de prueba:  node cifrar-propuesta.js test
   API:  const { wrapEncrypted } = require("./cifrar-propuesta");  await wrapEncrypted(html, password, {cliente, lang}) */
const nodeCrypto = require("crypto");
const ITERS = 150000;

// Cifrado con el modulo crypto de Node (sincrono). Produce salida que el
// navegador descifra con SubtleCrypto (PBKDF2 SHA-256 + AES-GCM, tag al final).
function encryptHtml(html, password) {
  const salt = nodeCrypto.randomBytes(16);
  const iv = nodeCrypto.randomBytes(12);
  const key = nodeCrypto.pbkdf2Sync(password, salt, ITERS, 32, "sha256");
  const cipher = nodeCrypto.createCipheriv("aes-256-gcm", key, iv);
  const ct = Buffer.concat([cipher.update(html, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return { salt: salt.toString("base64"), iv: iv.toString("base64"), ct: Buffer.concat([ct, tag]).toString("base64"), iters: ITERS };
}

const T = {
