function wrapEncrypted(html, password, meta) {
  meta = meta || {};
  const lang = (String(meta.lang || "es").toLowerCase().indexOf("en") === 0) ? "en" : "es";
  const cliente = meta.cliente || (lang === "en" ? "you" : "ti");
  const t = T[lang];
  const P = encryptHtml(html, password);
  const payload = JSON.stringify({ s: P.salt, i: P.iv, c: P.ct, it: P.iters });
  // JSON del payload embebido de forma segura
  const payloadTag = '<script type="application/json" id="pl">' + payload.replace(/</g, "\\u003c") + '<\/script>';
  return `<!DOCTYPE html><html lang="${lang}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="robots" content="noindex,nofollow"><title>${t.tag} - Siemon Digital</title>
<style>
