(function(){
  "use strict";
  var P = JSON.parse(document.getElementById("pl").textContent);
  var M = ${JSON.stringify({ errPass: t.errPass, errAccept: t.errAccept, errBrowser: t.errBrowser })};
  var acc = document.getElementById("acc"), pw = document.getElementById("pw"), go = document.getElementById("go"), err = document.getElementById("err");
  function sync(){ go.disabled = !acc.checked; }
  acc.addEventListener("change", sync); sync();
  function bytes(b64){ var s = atob(b64), a = new Uint8Array(s.length); for (var i=0;i<s.length;i++) a[i]=s.charCodeAt(i); return a; }
  function reveal(html){ document.open(); document.write(html); document.close(); }
  function open(){
    err.textContent = "";
    if (!acc.checked){ err.textContent = M.errAccept; return; }
    if (!window.crypto || !crypto.subtle){ err.textContent = M.errBrowser; return; }
    var enc = new TextEncoder();
    crypto.subtle.importKey("raw", enc.encode(pw.value||""), "PBKDF2", false, ["deriveKey"]).then(function(km){
      return crypto.subtle.deriveKey({ name:"PBKDF2", salt:bytes(P.s), iterations:P.it, hash:"SHA-256" }, km, { name:"AES-GCM", length:256 }, false, ["decrypt"]);
    }).then(function(key){
      return crypto.subtle.decrypt({ name:"AES-GCM", iv:bytes(P.i) }, key, bytes(P.c));
    }).then(function(buf){
      reveal(new TextDecoder().decode(buf));
    }).catch(function(){ err.textContent = M.errPass; });
  }
  go.addEventListener("click", open);
  pw.addEventListener("keydown", function(e){ if(e.key==="Enter" && !go.disabled) open(); });
})();
<\/script>
