/* Nucleo determinista del agente de propuestas (probado local; se porta al Code node de n8n).
   - computePrices(): precios con la rubrica provisoria.
   - fillTemplate(): reemplaza los placeholders [ ... ] de la plantilla con el contenido del LLM,
     precios calculados, datos del cliente, responsable y WhatsApp.
   Uso de prueba:  node build-propuesta-core.js test */



const HOURS = {
  "Automatización de procesos": 25, "IA aplicada": 30, "Estructuras y procesos de ventas": 20,
  "Optimización de recursos": 18, "Acompañamiento consultivo": 12, "Arquitectura a medida": 35
};

function computePrices(servicios, teamSize, complejidad, urgencia) {
  let hrs = (servicios || []).reduce((s, x) => s + (HOURS[x] || 20), 0);
  if (hrs === 0) hrs = 20;
  const t = String(teamSize || "");
  const mt = /20\+/.test(t) ? 1.6 : /(6-10|11-20|6-20)/.test(t) ? 1.3 : 1.0;
  const mc = complejidad === "alta" ? 1.6 : complejidad === "media" ? 1.25 : 1.0;
  const mu = /urgente/i.test(urgencia || "") ? 1.2 : 1.0;
  const proyecto = Math.max(1900, Math.ceil(hrs * 40 * mt * mc * mu / 100) * 100);
  const mensual = proyecto < 3000 ? 300 : proyecto < 6000 ? 500 : 800;
  return { entrada: 500, proyecto, mensual, hrs, mt, mc, mu };
}

function fmtMoney(n, lang) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, lang === "es" ? "." : ",");
}

// reemplazo literal (todas las ocurrencias) sin interpretar $
function repAll(html, key, val) { return html.split(key).join(val == null ? "" : String(val)); }
// reemplazo secuencial: 1a ocurrencia -> values[0], etc.; sobrantes -> ""
function repSeq(html, key, values) {
  let i = 0;
  while (html.indexOf(key) !== -1) {
    const v = i < values.length ? String(values[i] == null ? "" : values[i]) : "";
    html = html.replace(key, function () { return v; });
    i++;
  }
  return html;
}

function fillTemplate(tpl, lang, lead, resp, llm) {
  lang = (String(lang || "es").toLowerCase().indexOf("en") === 0) ? "en" : "es";
  const P = computePrices(lead.servicios, lead.team_size, llm.complejidad, lead.urgencia);
  // Override de precios si el responsable pidio un precio especifico en los ajustes
  const ov = llm.precio_override || {};
  const num = (v) => { const n = parseInt(String(v).replace(/[^0-9]/g, ""), 10); return n > 0 ? n : 0; };
  if (num(ov.proyecto)) P.proyecto = num(ov.proyecto);
  if (num(ov.mensual)) P.mensual = num(ov.mensual);
  if (num(ov.entrada)) P.entrada = num(ov.entrada);
  const money = (n) => fmtMoney(n, lang);
  const a = llm.analisis || {}, d = llm.diagnostico || {};
  const ent = llm.entregables || [], met = llm.metricas || [], inc = llm.incluye_plan_proyecto || [];
  const clienteCorto = lead.company || lead.name || (lang === "en" ? "your business" : "tu negocio");

  // singles: [placeholder, valor]
  const S = [];
  const seq = []; // {key, values}

  const tl = llm.timeline || [];
  const metVal = (i) => (met[i] || {}).valor || "";
  const metLbl = (i) => (met[i] || {}).etiqueta || "";
  const strip = (k) => k.replace(/^\[\s?/, "").replace(/\s?\]$/, "");
  const respName = (resp && resp.nombre) || "Andrea Siemon";

  if (lang === "es") {
    S.push(["[ nombre del cliente ]", lead.name || clienteCorto]);
    S.push(["[ cliente ]", clienteCorto]);
    S.push(["[ Andrea Siemon ]", respName]);
    S.push(["[ A qué se dedica el negocio ]", a.a_que_se_dedica]);
    S.push(["[ Descripción breve de su actividad, modelo o servicio principal. ]", a.descripcion_breve || a.a_que_se_dedica]);
    S.push(["[ Su objetivo o meta actual ]", a.objetivo_actual]);
    S.push(["[ Qué quiere lograr: escalar, vender más, ordenar procesos, etc. ]", a.objetivo_detalle || ""]);
    S.push(["[ Su momento o contexto ]", a.momento_contexto]);
    S.push(["[ Dónde está hoy y por qué este es el momento de actuar. ]", a.donde_esta_hoy]);
    S.push(["[ describe el reto principal del cliente en una frase ]", a.reto_una_frase]);
    S.push(["[ Amplía: qué consecuencia tiene ese reto en su día a día o en su crecimiento. ]", a.reto_detalle || ""]);
    S.push(["[ Hallazgo 1 del diagnóstico ]", d.hallazgo_1]);
    S.push(["[ Hallazgo 2 del diagnóstico ]", d.hallazgo_2]);
    S.push(["[ La oportunidad principal ]", d.oportunidad]);
    S.push(["[ Dónde está la palanca de mayor impacto. ]", d.oportunidad_detalle]);
    S.push(["[ el sistema / la estructura ]", d.sistema_estructura]);
    S.push(["[ tu meta ]", d.meta_cliente]);
    for (let i = 0; i < 6; i++) S.push(["[ Entregable " + (i + 1) + " ]", (ent[i] || {}).titulo || ""]);
    ["[ 00% ]", "[ 0× ]", "[ +00 ]", "[ 00 ]"].forEach((k, i) => S.push([k, metVal(i)]));
    for (let i = 0; i < 4; i++) S.push(["[ Métrica esperada " + (i + 1) + " ]", metLbl(i)]);
    for (let i = 0; i < 4; i++) S.push(["[ Incluye " + (i + 1) + " ]", inc[i] || ""]);
    S.push(["[ desde USD $1.900 ]", "desde USD $" + money(P.proyecto)]);
    S.push(["[ desde USD $300 ]", "desde USD $" + money(P.mensual)]);
    ["[ Sem. 1–2 ]", "[ Sem. 3–4 ]", "[ Sem. 5–7 ]", "[ Sem. 8+ ]"].forEach((k, i) => S.push([k, tl[i] || strip(k)]));
    ["[ desde USD $500 ]", "[ punto de entrada · 2–3 semanas ]", "[ por etapas, según alcance acordado ]", "[ mensual ]"].forEach(k => S.push([k, strip(k)]));
    seq.push({ key: "[ Qué detectamos y por qué importa. ]", values: [d.hallazgo_1_detalle, d.hallazgo_2_detalle] });
    seq.push({ key: "[ Detalle breve. ]", values: ent.map(e => (e || {}).detalle || "") });
  } else {
    S.push(["[ client name ]", lead.name || clienteCorto]);
    S.push(["[ client ]", clienteCorto]);
    S.push(["[ Andrea Siemon ]", respName]);
    S.push(["[ What the business does ]", a.a_que_se_dedica]);
    S.push(["[ Brief description of its activity, model or main service. ]", a.descripcion_breve || a.a_que_se_dedica]);
    S.push(["[ Its current objective or goal ]", a.objetivo_actual]);
    S.push(["[ What it wants to achieve: scale, sell more, organize processes, etc. ]", a.objetivo_detalle || ""]);
    S.push(["[ Its moment or context ]", a.momento_contexto]);
    S.push(["[ Where it is today and why now is the time to act. ]", a.donde_esta_hoy]);
    S.push(["[ describe the client's main challenge in one sentence ]", a.reto_una_frase]);
    S.push(["[ Expand: the impact that challenge has on their day-to-day or growth. ]", a.reto_detalle || ""]);
    S.push(["[ Finding 1 from the diagnosis ]", d.hallazgo_1]);
    S.push(["[ Finding 2 from the diagnosis ]", d.hallazgo_2]);
    S.push(["[ The main opportunity ]", d.oportunidad]);
    S.push(["[ Where the highest-impact lever is. ]", d.oportunidad_detalle]);
    S.push(["[ the system / the structure ]", d.sistema_estructura]);
    S.push(["[ your goal ]", d.meta_cliente]);
    for (let i = 0; i < 6; i++) S.push(["[ Deliverable " + (i + 1) + " ]", (ent[i] || {}).titulo || ""]);
    ["[ 00% ]", "[ 0× ]", "[ +00 ]", "[ 00 ]"].forEach((k, i) => S.push([k, metVal(i)]));
    for (let i = 0; i < 4; i++) S.push(["[ Expected metric " + (i + 1) + " ]", metLbl(i)]);
    for (let i = 0; i < 4; i++) S.push(["[ Includes " + (i + 1) + " ]", inc[i] || ""]);
    S.push(["[ from USD $1,900 ]", "from USD $" + money(P.proyecto)]);
    S.push(["[ from USD $300 ]", "from USD $" + money(P.mensual)]);
    ["[ Wk. 1–2 ]", "[ Wk. 3–4 ]", "[ Wk. 5–7 ]", "[ Wk. 8+ ]"].forEach((k, i) => S.push([k, tl[i] || strip(k)]));
    ["[ from USD $500 ]", "[ entry point · 2–3 weeks ]", "[ in stages, per agreed scope ]", "[ monthly ]"].forEach(k => S.push([k, strip(k)]));
    seq.push({ key: "[ What we detected and why it matters. ]", values: [d.hallazgo_1_detalle, d.hallazgo_2_detalle] });
    seq.push({ key: "[ Brief detail. ]", values: ent.map(e => (e || {}).detalle || "") });
  }

  let html = tpl;
  for (const [k, v] of S) html = repAll(html, k, v);
  for (const q of seq) html = repSeq(html, q.key, q.values);

  // WhatsApp del responsable: reemplaza el numero por defecto donde aparezca
  // (deck-config y fallback), robusto ante comillas escapadas de la plantilla standalone.
  const wa = String(resp && resp.whatsapp || "").replace(/[^0-9]/g, "");
