function computePrices(servicios, teamSize, complejidad, urgencia) {
  let hrs = (servicios || []).reduce((s, x) => s + (HOURS[x] || 20), 0);
  if (hrs === 0) hrs = 20;
  const t = String(teamSize || "");
  const mt = /20\+/.test(t) ? 1.6 : /(6-10|11-20|6-20)/.test(t) ? 1.3 : 1.0;
  const mc = complejidad === "alta" ? 1.6 : complejidad === "media" ? 1.25 : 1.0;
  const mu = /urgente/i.test(urgencia || "") ? 1.2 : 1.0;
  const proyecto = Math.max(1900, Math.ceil(hrs * 40 * mt * mc * mu / 100) * 100);
  const mensual = proyecto < 3000 ? 300 : proyecto < 6000 ? 500 : 800;
  return { entrada: 500, proyecto, mensual, hrs, mt, mc, mu };
}

function fmtMoney(n, lang) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, lang === "es" ? "." : ",");
}

// reemplazo literal (todas las ocurrencias) sin interpretar $
function repAll(html, key, val) { return html.split(key).join(val == null ? "" : String(val)); }
// reemplazo secuencial: 1a ocurrencia -> values[0], etc.; sobrantes -> ""
function repSeq(html, key, values) {
  let i = 0;
  while (html.indexOf(key) !== -1) {
    const v = i < values.length ? String(values[i] == null ? "" : values[i]) : "";
    html = html.replace(key, function () { return v; });
    i++;
  }
  return html;
}

